# region: fold
def fold(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: gather
def gather(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs):
    return {'n': len(xs) - 1, 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: render
def render(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(intake(emit(gather(fold(raw)))))

